def total_valid(values):
    total = 0
    for v in values:
        try:
            total += float(v)
        except (ValueError, TypeError):
            continue
    return total

def count_invalid(values):
    count = 0
    for v in values:
        try:
            int(v)
        except (ValueError, TypeError):
            count += 1
    return count

