def combine(*lists):
    result = []
    for lst in lists:
        result.extend(lst)
    return result

def describe_person(**kwargs):
    parts = []
    for key in sorted(kwargs):
        parts.append(f'{key}={kwargs[key]}')
    return ', '.join(parts)

